// Des: Tests the parallel database mirror: spool, order, dialect, backfill
// Flo: three mock databases + temp Db > run statements through the fan > assert every log
// I/O: statements > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const cmok = @import("sy-clou-mock.zig"); const mirr = @import("sy-mirr-stor.zig"); const msql = @import("sy-mirr-sqlz.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const sync = @import("sy-clou-sync.zig"); const fail = @import("ru-fail-over.zig");
const allo = std.testing.allocator; const NOWZ: i64 = 1795600000000;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, c1zz: cmok.Mock, c2zz: cmok.Mock, c3zz: cmok.Mock, mems: [3]msql.Smem, stat: mirr.Dead, ddlz: [3]bool, sanz: msql.Sanz,
fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.c1zz = cmok.Mock.init(allo); self.c2zz = cmok.Mock.init(allo); self.c3zz = cmok.Mock.init(allo); self.c3zz.dial = .mysq; self.mems = .{ .{ .name = "turs", .sql2 = self.c1zz.sql2(), .idxz = 0 }, .{ .name = "neon", .sql2 = self.c2zz.sql2(), .idxz = 1 }, .{ .name = "tidb", .sql2 = self.c3zz.sql2(), .idxz = 2 } }; self.stat = try mirr.deadMake(self.aren.allocator(), 3); self.ddlz = .{ false, false, false }; self.sanz = .{ .dbzz = &self.dbzz, .iozz = std.testing.io, .nowz = NOWZ, .conf = .{}, .prim = self.mems[0], .mirs = self.mems[1..], .stat = &self.stat, .ddlz = &self.ddlz }; }
fn down(self: *Rigg) void { self.c1zz.deinit(); self.c2zz.deinit(); self.c3zz.deinit(); self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); }
fn frsh(self: *Rigg) void { @memset(self.stat.dead, false); @memset(self.stat.used, false); }
fn exec(self: *Rigg, stms: []const []const u8) !void { const sqlx = msql.sanzSqlz(&self.sanz); try sqlx.exec(sqlx.ctx2, self.aren.allocator(), std.testing.io, stms); } };
fn upsz(aren: std.mem.Allocator, hexz: []const u8, body: []const u8) ![]const u8 { const cols = [_]sqlz.Colz{ .{ .name = "urlh", .valu = try sqlz.litz(aren, .sqlt, hexz) }, .{ .name = "body", .valu = try sqlz.litz(aren, .sqlt, body) } }; return sqlz.upse(aren, .sqlt, "cl_reco", "urlh", &cols); }
test "a statement reaches the main vendor and both mirrors in parallel, DDL once, MySQL gets its own form" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); try rig3.exec(&sqlz.DDL); try std.testing.expectEqual(@as(usize, 4), rig3.c1zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 4), rig3.c2zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 4), rig3.c3zz.stm2.items.len); try rig3.exec(&sqlz.DDL); try std.testing.expectEqual(@as(usize, 8), rig3.c1zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 4), rig3.c2zz.stm2.items.len); const stam = [_][]const u8{ try upsz(aren, "a1", "one"), try upsz(aren, "a2", "tw\\o") }; try rig3.exec(&stam); try std.testing.expectEqual(@as(usize, 10), rig3.c1zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 6), rig3.c2zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 6), rig3.c3zz.stm2.items.len); try std.testing.expectEqualStrings(stam[1], rig3.c2zz.stm2.items[5]); try std.testing.expect(std.mem.indexOf(u8, rig3.c3zz.stm2.items[5], "ON DUPLICATE KEY UPDATE body=VALUES(body)") != null); try std.testing.expect(std.mem.indexOf(u8, rig3.c3zz.stm2.items[5], "tw\\\\o") != null); try std.testing.expect(std.mem.indexOf(u8, rig3.c3zz.stm2.items[5], "ON CONFLICT") == null); try std.testing.expectEqual(@as(i64, 0), try msql.sanzLeft(&rig3.sanz)); try std.testing.expectEqual(@as(u32, 12), rig3.sanz.sent); }
test "a down mirror keeps the order in its spool, is skipped for the run, and catches up in order" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); try rig3.exec(&sqlz.DDL); rig3.c2zz.sqlo = true; const sta1 = [_][]const u8{try upsz(aren, "k1", "v1")}; const sta2 = [_][]const u8{try upsz(aren, "k2", "v2")}; const sta3 = [_][]const u8{"DELETE FROM cl_reco WHERE urlh='k1'"}; try rig3.exec(&sta1); try std.testing.expect(rig3.stat.dead[1] and !rig3.stat.dead[2]); try rig3.exec(&sta2); try rig3.exec(&sta3); try std.testing.expectEqual(@as(i64, 3), try msql.sanzLeft(&rig3.sanz)); try std.testing.expectEqual(@as(usize, 7), rig3.c3zz.stm2.items.len); rig3.c2zz.sqlo = false; rig3.frsh(); try msql.sanzDrai(&rig3.sanz, aren); try std.testing.expectEqual(@as(i64, 0), try msql.sanzLeft(&rig3.sanz)); try std.testing.expectEqual(@as(usize, 7), rig3.c2zz.stm2.items.len); try std.testing.expectEqualStrings(sta1[0], rig3.c2zz.stm2.items[4]); try std.testing.expectEqualStrings(sta2[0], rig3.c2zz.stm2.items[5]); try std.testing.expectEqualStrings(sta3[0], rig3.c2zz.stm2.items[6]); }
test "the main vendor failing is returned, the mirrors still keep their copy" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); try rig3.exec(&sqlz.DDL); rig3.c1zz.sqlo = true; const sta1 = [_][]const u8{try upsz(aren, "k1", "v1")}; try std.testing.expectError(error.CloudSql, rig3.exec(&sta1)); try std.testing.expectEqual(@as(usize, 5), rig3.c2zz.stm2.items.len); try std.testing.expectEqual(@as(usize, 5), rig3.c3zz.stm2.items.len); }
test "a spool over the cap is dropped and the mirror restarts from a backfill" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); rig3.sanz.conf.clou_mirr_spoo_maxz = 3; rig3.c2zz.sqlo = true; try rig3.exec(&sqlz.DDL); try fail.flagSetz(&rig3.dbzz, "msql_neon", 1); const stmz = [_][]const u8{ try upsz(aren, "a", "1"), try upsz(aren, "b", "2"), try upsz(aren, "c", "3"), try upsz(aren, "d", "4") }; try rig3.exec(&stmz); try std.testing.expectEqual(@as(usize, 1), rig3.sanz.drps.items.len); try std.testing.expectEqualStrings("neon", rig3.sanz.drps.items[0]); try std.testing.expectEqual(@as(i64, 0), try fail.flagGetz(&rig3.dbzz, "msql_neon")); try std.testing.expectEqual(@as(i64, 0), try msql.sanzLeft(&rig3.sanz)); }
test "backfill rebuilds a frsh mirror from the local tables in chunks, then stops" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const aren = rig3.aren.allocator(); rig3.sanz.conf.clou_mirr_batz = 2; for ([_][]const u8{ "http://a/1", "http://a/2", "http://a/3" }) |urlz| { try inde.pageSetz(&rig3.dbzz, urlz, .{ .hexz = "h", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = NOWZ, .next = 2 }); try inde.recoSetz(&rig3.dbzz, urlz, .{ .hexz = "h", .kind = "text", .body = "b" }, NOWZ); } for ([_][]const u8{ "h1", "h2", "h3" }) |hexz| { var insz = try rig3.dbzz.prep("INSERT INTO pack(hexz,packk,offs,lenz,vfyz,vend) VALUES(?1,'runs/p1',0,5,1,'turs');"); defer insz.fini(); try insz.bindText(1, hexz); _ = try insz.step(); } { var insz = try rig3.dbzz.prep("INSERT INTO purg(packz,timz,ents,stat) VALUES('runs/old',5,2,1);"); defer insz.fini(); _ = try insz.step(); } var synz: sync.Sync = .{ .iozz = std.testing.io, .dbzz = &rig3.dbzz, .dirz = rig3.dirz, .conf = .{}, .store = rig3.c1zz.store(), .sql2 = msql.sanzSqlz(&rig3.sanz) }; var tota: u32 = 0; var guar: u32 = 0; while (try fail.flagGetz(&rig3.dbzz, "msql_neon") != 1 or try fail.flagGetz(&rig3.dbzz, "msql_tidb") != 1) { tota += try msql.sanzBack(&rig3.sanz, aren, &synz); guar += 1; try std.testing.expect(guar < 20); } try std.testing.expectEqual(@as(u32, 6 + 3 + 1), tota / 2); rig3.sanz.conf.clou_mirr_batz = 500; try msql.sanzDrai(&rig3.sanz, aren); try std.testing.expectEqual(@as(usize, 10), rig3.c2zz.sawzStmt("INSERT INTO cl_")); try std.testing.expectEqual(@as(usize, 0), rig3.c1zz.stm2.items.len); try std.testing.expectEqual(@as(u32, 0), try msql.sanzBack(&rig3.sanz, aren, &synz)); try std.testing.expect(rig3.c3zz.sawzStmt("ON DUPLICATE KEY UPDATE") >= 1); }
